   789  static int processTLSBlock(struct ndpi_detection_module_struct *ndpi_struct,
   790                             struct ndpi_flow_struct *flow) {
   791    struct ndpi_packet_struct *packet = &ndpi_struct->packet;
   792    int ret;
   793
   794  #ifdef DEBUG_TLS
   795    printf("[TLS] Processing block %u\n", packet->payload[0]);
   796  #endif
   797
   798    switch(packet->payload[0] /* block type */) {
   799    case 0x01: /* Client Hello */
   800    case 0x02: /* Server Hello */
   801      processClientServerHello(ndpi_struct, flow, 0);
   802      flow->protos.tls_quic.hello_processed = 1;
   803      ndpi_int_tls_add_connection(ndpi_struct, flow, NDPI_PROTOCOL_TLS);
   804
   805  #ifdef DEBUG_TLS
   806      printf("*** TLS [version: %02X][%s Hello]\n",
   807             flow->protos.tls_quic.ssl_version,
   808             (packet->payload[0] == 0x01) ? "Client" : "Server");
   809  #endif
   810
   811      if((flow->protos.tls_quic.ssl_version >= 0x0304 /* TLS 1.3 */)
   812         && (packet->payload[0] == 0x02 /* Server Hello */)) {
   813        flow->l4.tcp.tls.certificate_processed = 1; /* No Certificate with TLS 1.3+ */
   814      }
   815
   816      checkTLSSubprotocol(ndpi_struct, flow);
   817      break;
   818
   819    case 0x0b: /* Certificate */
   820      /* Important: populate the tls union fields only after
   821       * ndpi_int_tls_add_connection has been called */
   822      if(flow->protos.tls_quic.hello_processed) {
   823        ret = processCertificate(ndpi_struct, flow);
   824        if(ret != 1) {
   825  #ifdef DEBUG_TLS
   826          printf("[TLS] Error processing certificate: %d\n", ret);
   827  #endif
   828        }
   829        flow->l4.tcp.tls.certificate_processed = 1;
   830      }
   831      break;
   832
   833    default:
   834      return(-1);
   835    }
   836
   837    return(0);
   838  }
